// Turn the sheet's usedRange values into one ingest array.
// The backend forward-fills org, splits the follow-up date+hook, and parses dates.
const rows = $json.values || [];
if (rows.length < 2) return [{ json: { payload: [] } }];
const header = rows[0].map(h => (h || '').toString().trim().toLowerCase());
const col = (name) => header.findIndex(h => h.startsWith(name));
const idx = {
  organisation: col('organisation'), contact_name: col('name'),
  topic: col('topic of concern'), email: col('email'),
  last_contact_raw: col('last day of contact'),
  next_followup_raw: col('next followup'),
  summary: col('overall summary'), next_steps: col('next steps'),
};
const pick = (r, i) => (i >= 0 && r[i] != null && String(r[i]).trim() !== '') ? String(r[i]) : null;
const payload = rows.slice(1).map(r => ({
  organisation: pick(r, idx.organisation),
  contact_name: pick(r, idx.contact_name),
  email: pick(r, idx.email),
  topic: pick(r, idx.topic),
  last_contact_raw: pick(r, idx.last_contact_raw),
  next_followup_raw: pick(r, idx.next_followup_raw),
  summary: pick(r, idx.summary),
  next_steps: pick(r, idx.next_steps),
}));
return [{ json: { payload } }];
